CREATE TABLE cafes (
  id TEXT PRIMARY KEY,
  source_row_number INTEGER UNIQUE,
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  area_id INTEGER NOT NULL REFERENCES areas(area_id),
  location TEXT NOT NULL,
  cuisine_source TEXT NOT NULL,
  niche_type TEXT NOT NULL,
  timing TEXT NOT NULL,
  weekday_hours TEXT,
  weekend_hours TEXT,
  hours_note TEXT,
  contact_details_number TEXT NOT NULL DEFAULT '',
  price_range TEXT NOT NULL DEFAULT '',
  price_for_two REAL NOT NULL DEFAULT 0.00,
  rating REAL,
  vibe_ambiance TEXT NOT NULL,
  more_info TEXT NOT NULL,
  maps_url TEXT,
  status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
