CREATE TABLE users (
  user_id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  phone_number TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  profile_image_path TEXT,
  role TEXT NOT NULL DEFAULT 'user',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO users VALUES(1,'admin','9876543210','$2y$12$fHNGTuNTI1OZC8TdpBAG8O21G2brHhsZTGL/AdO407AG.yfyqg3vS',NULL,'admin','2026-10-23 14:14:34.000000');
CREATE TABLE favorites (
  user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  cafe_id TEXT NOT NULL REFERENCES cafes(id) ON DELETE CASCADE,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, cafe_id)
);
CREATE TABLE reviews (
  review_id INTEGER PRIMARY KEY AUTOINCREMENT,
  cafe_id TEXT NOT NULL REFERENCES cafes(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  review_text TEXT NOT NULL,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
